#!/usr/bin/env node
// `just dashboard`: the D3 dashboard's local server (127.0.0.1 only).
//   GET  /                -> app/dashboard/*
//   GET  /data/deployment -> deployments/<CHAIN_ID>.json (contracts, gate-a, scenes, reputation)
//   GET  /data/exo010     -> kit/out/exo010.json (the simulation; generated by `just sim` if missing)
//   GET  /data/config     -> { chainId, rpcLabel, explorerUrl }
//   POST /rpc             -> JSON-RPC proxy to RPC_URL (the browser never needs CORS on the node)
//   POST /api/crash       -> runs `scene crash` with the server's env (the .env devnet key stays here),
//                            streaming its output as text. Switch chains by changing CHAIN_ID / RPC_URL.
import { createServer } from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { spawn, spawnSync } from "node:child_process";
import { join, dirname, extname, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const STATIC = join(ROOT, "app", "dashboard");
const CHAIN_ID = process.env.CHAIN_ID ?? "1337";
const RPC_URL = process.env.RPC_URL ?? "https://altmempoolgateway.forshtat.com/rpc";
const EXPLORER = process.env.EXPLORER_URL ?? "https://explorer.altmempool.wtf/";
const PORT = Number(process.env.DASHBOARD_PORT ?? 5173);
const TYPES = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8" };
let crashRunning = false;

const send = (res, code, body, type = "application/json") => {
  res.writeHead(code, { "content-type": type, "cache-control": "no-store" });
  res.end(body);
};
const readJson = (p) => (existsSync(p) ? readFileSync(p, "utf8") : null);

createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  try {
    if (req.method === "GET" && url.pathname === "/data/config") {
      return send(res, 200, JSON.stringify({ chainId: Number(CHAIN_ID), rpcLabel: new URL(RPC_URL).host, explorerUrl: EXPLORER }));
    }
    if (req.method === "GET" && url.pathname === "/data/deployment") {
      const j = readJson(join(ROOT, "deployments", `${CHAIN_ID}.json`));
      return j ? send(res, 200, j) : send(res, 404, JSON.stringify({ error: `deployments/${CHAIN_ID}.json not found: run just gate-a` }));
    }
    if (req.method === "GET" && url.pathname === "/data/exo010") {
      const p = join(ROOT, "kit", "out", "exo010.json");
      if (!existsSync(p)) spawnSync("node", ["--import", "tsx", "scripts/gen-exo010-chart.mjs"], { cwd: join(ROOT, "kit") });
      return send(res, 200, readJson(p) ?? "null");
    }
    if (req.method === "POST" && url.pathname === "/rpc") {
      let body = "";
      for await (const c of req) body += c;
      const r = await fetch(RPC_URL, { method: "POST", headers: { "content-type": "application/json" }, body });
      return send(res, r.status, await r.text());
    }
    if (req.method === "POST" && url.pathname === "/api/crash") {
      if (crashRunning) return send(res, 409, "a crash scene is already running\n", "text/plain");
      crashRunning = true;
      res.writeHead(200, { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" });
      const p = spawn("npx", ["tsx", "src/scenes/run.ts", "crash"], { cwd: join(ROOT, "kit"), env: { ...process.env, CHAIN_ID } });
      const pk = process.env.PRIVATE_KEY;
      const scrub = (b) => (pk ? b.toString().replaceAll(pk, "<redacted>") : b.toString());
      p.stdout.on("data", (b) => res.write(scrub(b)));
      p.stderr.on("data", (b) => res.write(scrub(b)));
      p.on("close", (code) => {
        crashRunning = false;
        res.end(`\n[scene crash exited ${code}]\n`);
      });
      return;
    }
    if (req.method === "GET") {
      const rel = normalize(url.pathname === "/" ? "/index.html" : url.pathname).replace(/^(\.\.[/\\])+/, "");
      const file = join(STATIC, rel);
      if (!file.startsWith(STATIC) || !existsSync(file)) return send(res, 404, "not found", "text/plain");
      return send(res, 200, readFileSync(file), TYPES[extname(file)] ?? "application/octet-stream");
    }
    send(res, 405, "method not allowed", "text/plain");
  } catch (e) {
    send(res, 500, JSON.stringify({ error: String(e?.message ?? e) }));
  }
}).listen(PORT, "127.0.0.1", () => console.log(`dashboard: http://127.0.0.1:${PORT}  (chain ${CHAIN_ID}, rpc ${new URL(RPC_URL).host})`));
